mapper.select:
		select t1.*,
			   s.subject_type as subjectType,
			   s.id as subjectId,
			   s.tenant_id as tenantId,
			   s.merchant_id as merchantId,
			   s.dept_id as deptId,
			   (select ru.role_id from sys_role_user ru where ru.user_subject_id = s.id order by ru.id asc limit 1) as roleId,
			   (select t2.name from sys_dept t2 where t2.id=s.dept_id) deptName,
        	   (SELECT t3.NAME FROM sys_tenant t3 WHERE t3.id = s.tenant_id) tenantName
			from sys_user t1
			left join sys_user_subject s on s.user_id = t1.id
			where 1 = 1

			and t1.username like #{username}


			and s.dept_id = #{deptId}


            and s.tenant_id = #{tenantId}


            and s.merchant_id = #{merchantId}


			and t1.gender = #{gender}


			and t1.id != #{selfId}


			and s.dept_id in

				#{id}



            and s.tenant_id in

                #{id}

mapper.update:
update sys_user
set auth_type = #{authType},
	auth_secret = #{authSecret}
where id = #{id}
